#!/usr/bin/env python3
"""Condense a captured conversation-logs JSONL into a readable timeline with timestamps."""
import json
import sys

def trunc(s, n=300):
    s = str(s)
    return s if len(s) <= n else s[:n] + f'...[{len(s)}chars]'

def summarize_content(content):
    if isinstance(content, str):
        return trunc(content)
    out = []
    if isinstance(content, list):
        for block in content:
            if not isinstance(block, dict):
                out.append(trunc(block))
                continue
            t = block.get('type')
            if t == 'text':
                out.append(trunc(block.get('text', '')))
            elif t == 'tool_use':
                out.append(f"TOOL_USE {block.get('name')} input={trunc(block.get('input'), 200)}")
            elif t == 'tool_result':
                c = block.get('content')
                out.append(f"TOOL_RESULT {trunc(c, 200)}")
            elif t == 'thinking':
                out.append(f"THINKING {trunc(block.get('thinking',''), 150)}")
            else:
                out.append(f"{t}: {trunc(block, 150)}")
    return ' | '.join(out)

def main(path):
    with open(path) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                entry = json.loads(line)
            except json.JSONDecodeError:
                print("PARSE_ERROR:", trunc(line, 100))
                continue
            ts = entry.get('timestamp', '')
            typ = entry.get('type', entry.get('role', '?'))
            msg = entry.get('message', entry)
            role = msg.get('role', typ) if isinstance(msg, dict) else typ
            content = msg.get('content') if isinstance(msg, dict) else None
            summary = summarize_content(content) if content is not None else trunc(entry, 200)
            print(f"[{ts}] {role}: {summary}")

if __name__ == '__main__':
    main(sys.argv[1])

